messages.content:
Tool response:
Tool: search_listings
Description: Search Listings
Parameters:
    {
      "type": "object",
      "properties": {
        "location": {
          "type": "string",
          "title": "Location",
          "description": ""
        },
        "check_in": {
          "type": "string",
          "format": "date",
          "title": "Check In",
          "description": ""
        },
        "check_out": {
          "type": "string",
          "format": "date",
          "title": "Check Out",
          "description": ""
        },
        "min_bedrooms": {
          "anyOf": [
            {
              "type": "integer"
            },
            {
              "type": "null"
            }
          ],
          "default": 2,
          "title": "Min Bedrooms",
          "description": ""
        },
        "min_price": {
          "anyOf": [
            {
              "type": "number"
            },
            {
              "type": "null"
            }
          ],
          "default": 120,
          "title": "Min Price",
          "description": ""
        },
        "max_price": {
          "anyOf": [
            {
              "type": "number"
            },
            {
              "type": "null"
            }
          ],
          "default": 350,
          "title": "Max Price",
          "description": ""
        },
        "amenities": {
          "anyOf": [
            {
              "type": "array",
              "items": {
                "type": "string"
              }
            },
            {
              "type": "null"
            }
          ],
          "title": "Amenities",
          "description": ""
        }
      },
      "required": [
        "location",
        "check_in",
        "check_out"
      ]
    }
